64 |     uint timeRemaining = fromKey.expirationTimestamp - block.timestamp;
65 |     // get the transfer fee based on amount of time wanted share
66 |     uint fee = getTransferFee(keyOwner, _timeShared);
67 |     uint timePlusFee = _timeShared + fee;
